"""Local-only observer. Remote metadata is always inserted as text, never HTML."""
DASHBOARD = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agent Marketplace</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{font:14px system-ui;margin:0;background:#0c1220;color:#e4ecfa}main{max-width:1280px;margin:28px auto;padding:0 24px}header{display:flex;align-items:center;justify-content:space-between}h1{font-size:28px;letter-spacing:-.5px;margin:4px 0}h2{font-size:16px;margin:0 0 10px}.tag{font-size:12px;padding:8px 12px;border:1px solid #3b4966;border-radius:30px;color:#b8c8e3;font-weight:600}.notice{padding:12px 16px;border:1px solid #725b31;background:#241f16;border-radius:10px;color:#edd399;margin:14px 0}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.card{background:#141e31;border:1px solid #273753;border-radius:12px;padding:16px;overflow:auto}.number{font-size:26px;font-weight:650;margin-top:4px}.muted{color:#9aaac4}.columns{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.wide{margin-top:14px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:7px 6px;border-bottom:1px solid #2a3750;vertical-align:top}th{color:#9cacc5;font-weight:500}.log{font:12px ui-monospace,monospace;white-space:pre-wrap;overflow:auto;max-height:260px;margin:0}.refused{border-color:#7a3b3b;background:#241618}.refused b{color:#f0a7a7}.verified{border-color:#2f7a55;background:#14261e}.verified b{color:#85dfaf}@media(max-width:900px){.columns,.stats{grid-template-columns:1fr}header{display:block}}</style>
<main><header><div><span class="muted">META HACKATHON</span><h1>Agent Marketplace</h1></div><span class="tag" id="status">Connecting</span></header><div class="notice" id="notice">Connecting.</div>
<section class="stats"><div class="card"><span class="muted">Accepted modules</span><div class="number" id="accepted">-</div></div><div class="card"><span class="muted">Simulated credits settled</span><div class="number" id="settled">-</div></div><div class="card"><span class="muted">Attempts / failed</span><div class="number" id="attempts">-</div></div><div class="card"><span class="muted">Repairs</span><div class="number" id="repairs">-</div></div><div class="card"><span class="muted">Meta API spend (guard estimate)</span><div class="number" id="spend">-</div><span class="muted" id="spend-detail"></span></div></section>
<div class="columns"><section class="card"><h2>Plan <span class="muted" id="plan-source"></span></h2><table><thead><tr><th>Module</th><th>Depends on</th><th>Complexity</th><th>Status</th><th>Rationale</th></tr></thead><tbody id="tasks"></tbody></table></section><section class="card"><h2>Workers</h2><table><thead><tr><th>Worker</th><th>Provider / model</th><th>Live</th><th>Execution</th></tr></thead><tbody id="workers"></tbody></table></section></div>
<section class="card wide"><h2>Attempts and why each worker won</h2><table><thead><tr><th>Module</th><th>Worker</th><th>Result</th><th>Offers (quote)</th><th>Selection</th><th>Model</th><th>Latency</th><th>Tokens in/out</th><th>Cost</th><th>Feedback</th></tr></thead><tbody id="timeline"></tbody></table></section>
<div class="columns"><section class="card refused" id="protected-card"><h2>Protected execution</h2><p><b id="confidential-state"></b></p><p class="muted" id="confidential-reason"></p></section><section class="card"><h2>Verified application</h2><pre class="log" id="report">Waiting for independently accepted artifacts.</pre></section></div>
<section class="card wide"><h2>Events</h2><div class="log" id="events"></div></section></main><script>
const text=(id,value)=>document.getElementById(id).textContent=String(value);
function rows(id,values){const parent=document.getElementById(id);parent.replaceChildren();for(const cells of values){const tr=document.createElement('tr');for(const value of cells){const td=document.createElement('td');td.textContent=String(value??'-');tr.appendChild(td)}parent.appendChild(tr)}}
function notice(s){const providers=new Set(s.market.workers.map(w=>w.provider));if(providers.has('simulated-meta'))return 'SIMULATED REHEARSAL: prewritten responses through the real code paths. No AI inference. Workers are ordinary processes.';if(providers.has('fixture'))return 'FIXTURE: workers return prewritten code, not AI inference. Workers are ordinary processes.';return 'Marketplace workers: live model output on ordinary processes, for public work that their hosts can read. Only the Protected execution panel makes a confidentiality claim, within the limits it states.'}
function protectedView(pr,policy){
const view=(title,reason,className='card refused')=>({title,reason,className});
if(!pr)return view('REFUSED: ordinary marketplace workers cannot receive private data',(policy?.reason||'Ordinary workers do not establish host confidentiality')+'. No separate protected-task release or delivery state has been recorded.');
const released=pr.release_state,delivery=pr.delivery_state;
if(!((released==='not_released'&&delivery==='not_submitted')||(released==='submitted'&&(delivery==='unknown'||delivery==='response_received'))))return view('UNKNOWN: private release and delivery state were not recorded','This record does not establish whether private data was released. '+(pr.reason||''));
if(released==='not_released')return view(pr.verified?'NOT RELEASED: protected submission did not start':'REFUSED: no private data was released',pr.reason||'Protected submission did not start.');
if(delivery==='unknown'||!pr.verified)return view('SUBMITTED: delivery or execution is unknown',(pr.verified?'Attestation passed before encrypted submission. ':'')+(pr.reason||'The worker may have received or executed the task; no accepted result is available.'));
let detail=pr.reason||'An authenticated response was received; independent acceptance did not pass.';
if(pr.model&&Number.isFinite(pr.inference_ms)&&Number.isInteger(pr.correct)&&Number.isInteger(pr.rows))detail='Private rows sealed ('+pr.ciphertext_bytes+' bytes of ciphertext) and processed by '+pr.model+' in '+(pr.inference_ms/1000).toFixed(1)+'s. Independent check: '+pr.correct+'/'+pr.rows+', '+(pr.accepted?'accepted':'rejected')+'.';
const check=pr.refusal_check_status==='refused'?'refused':pr.refusal_check_status==='failed'?'FAILED':'unavailable';
if(typeof pr.product==='string'&&typeof pr.host_data==='string')detail='AMD '+pr.product+' report; approved guest and policy '+pr.host_data.slice(0,12)+'..., fresh nonce and key bound. '+detail;
detail+=' Unapproved policy check: '+check+'. AMD and Microsoft remain trusted; side channels excluded. This task bypasses bidding and credits.';
return view(pr.accepted?'VERIFIED before release: protected task accepted':'RESPONSE RECEIVED: protected task not accepted',detail,pr.accepted&&check!=='FAILED'?'card verified':'card refused');
}
async function refresh(){try{const response=await fetch('/v1/status',{cache:'no-store'});if(!response.ok)throw Error();const s=await response.json(),m=s.market,plan=s.plan||{tasks:{}};
text('status',s.complete?'Integration passed':'Executing');text('notice',notice(s));text('accepted',s.tasks.filter(t=>t.accepted).length+' / '+s.tasks.length);text('settled',m.credits.settled);text('attempts',m.attempts.length+' / '+m.attempts.filter(a=>a.status==='expired'||a.status==='rejected').length);text('repairs',s.attempts.filter(a=>a.repair_round>0).length);
if(s.budget){text('spend','$'+s.budget.used_usd.toFixed(4));text('spend-detail','Run $'+s.budget.run_used_usd.toFixed(4)+'. Cap $'+s.budget.cap_usd.toFixed(2)+', hard ceiling $'+s.budget.hard_ceiling_usd.toFixed(2))}else{text('spend','$0');text('spend-detail','No hosted calls')}
text('plan-source','source: '+(plan.source||'pending')+(plan.model?' / '+plan.model:'')+(plan.rejected_reason?' ('+plan.rejected_reason+')':''));
rows('tasks',s.tasks.map(t=>{const p=plan.tasks[t.kind]||{};return[t.kind,(p.depends_on||[]).join(', ')||'none',p.complexity,t.accepted?'Accepted + paid':'Pending',p.rationale]}));
rows('workers',m.workers.map(w=>[w.worker_id,w.provider+' / '+w.model,w.live?'yes':'no',w.security_mode]));
rows('timeline',s.attempts.map(a=>[a.kind,a.worker_id,a.status+(a.repair_round?' (repair)':''),a.offers.map(o=>o.worker_id+': '+o.credits).join(', '),a.selection,a.model,a.elapsed_ms==null?null:(a.elapsed_ms/1000).toFixed(1)+'s',a.usage&&a.usage.prompt_tokens!=null?a.usage.prompt_tokens+' / '+a.usage.completion_tokens:null,a.cost_usd==null?null:'$'+a.cost_usd.toFixed(4),a.diagnostic||(a.failure?'provider status '+a.failure:null)]));
const protectedStatus=protectedView(s.protected,s.confidential_policy);document.getElementById('protected-card').className=protectedStatus.className;text('confidential-state',protectedStatus.title);text('confidential-reason',protectedStatus.reason);
text('report',s.integration?JSON.stringify(s.integration.report,null,2):'Waiting for independently accepted artifacts.');text('events',s.events.slice(-20).reverse().map(e=>e.event+(e.worker_id?' · '+e.worker_id:'')+(e.reason?' · '+e.reason:'')).join('\n'))}catch{text('status','Observer disconnected')}}refresh();setInterval(refresh,1000);
</script></html>'''
